/bin/bash -lc "python - <<'PY'
import pathlib,re,subprocess,collections,ast,json
files=[pathlib.Path(f) for f in subprocess.check_output(['git','ls-files','-z']).decode().split('\\0') if f]
texts={}
for f in files:
 try:texts[f]=f.read_text()
 except (UnicodeError,OSError):pass
replacements={}
for f,s in texts.items():
 for kind,p in [('github',r'\\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})\\b'),('huggingface',r'\\bhf_[A-Za-z0-9]{20,}\\b'),('aws-access-key-id',r'\\b(?:AKIA|ASIA)[A-Z0-9]{16}\\b')]:
  for m in re.finditer(p,s):replacements[m[0]]='<your-'+('github-token' if kind=='github' else 'huggingface-token' if kind=='huggingface' else kind)+'>'
 for key,kind in [('AWS_ACCESS_KEY_ID','aws-access-key-id'),('AWS_SECRET_ACCESS_KEY','aws-secret-access-key')]:
  for p in [rf'{key}=(["'^'"\\s\\\"\\']+)',rf'{key}[\\\"\\']\\]\\s*=\\s*[\\\"\\'](["'^'"\\\"\\']+)[\\\"\\']']:
   for m in re.finditer(p,s):
    v=m[1]
    if not v.startswith(('<','"'$'"','[')) and v not in ('None','REDACTED'):replacements[v]='<your-'+kind+'>'
print('Unique credentials by type:',dict(collections.Counter(replacements.values())))
changed=[]
for f,s in texts.items():
 t=s
 for secret,placeholder in replacements.items():t=t.replace(secret,placeholder)
 if t"'!=s:
  f.write_text(t);changed.append(f)
  print('"'Sanitized',f,'replacements',sum(s.count(v) for v in replacements))
for f in files:
 data=f.read_bytes()
 assert not any(v.encode() in data for v in replacements),str(f)
for f in changed:
 if f.suffix=='.py':ast.parse(f.read_text())
 if f.suffix=='.json':json.loads(f.read_text())
# Verify exact byte replacement against HEAD for changed files; no unrelated modifications.
for f in changed:
 original=subprocess.check_output(['git','show','HEAD:'+str(f)])
 expected=original
 for v,p in replacements.items():expected=expected.replace(v.encode(),p.encode())
 assert f.read_bytes()==expected,str(f)
print('Verified original values absent from all tracked working files; edits are exact replacements; Python/JSON parse successfully.')
# Check reachable history without displaying secrets.
objects=subprocess.check_output(['git','rev-list','--objects','--all']).splitlines()
matched=set()
for entry in objects:
 oid=entry.split(b' ',1)[0].decode()
 kind=subprocess.check_output(['git','cat-file','-t',oid]).strip()
 if kind"'!=b'"'blob':continue
 data=subprocess.check_output(['git','cat-file','blob',oid])
 if any(v.encode() in data for v in replacements):matched.add(oid)
print('Historical blobs containing identified credentials:',len(matched))
PY"

