import pathlib,subprocess,re
patterns=re.compile(r'(?i)secret|credential|token|api.?key|authorization|password|passwd|private.key|client.?secret|connection.?string')
for f in subprocess.check_output(['git','ls-files','-z']).decode().split('\\0'):
 if not f or f.startswith(('exp_data/','data/','tests/')) or f.endswith('.tiktoken'):continue
 try:s=pathlib.Path(f).read_text()
 except (UnicodeError,OSError):continue
 for i,l in enumerate(s.splitlines(),1):
  if patterns.search(l) and re.search(r'[\\\"\\'][A-Za-z0-9+/=_-]{25,}[\\\"\\']',l):
   print(f,i,re.sub(r'([\\\"\\']).*?\\1','<quoted-value>',l)[:180])
# Check untracked/ignored files and configuration without exposing contents.
for f in subprocess.check_output(['git','ls-files','--others','-z']).decode().split('\\0'):
 if f:print('Untracked file:',f)
config=pathlib.Path('.git/config').read_text()
print('Git config authenticated URL:',bool(re.search(r'https?://["'^/'"\\s]+:["'^/'"\\s]+@',config)))
